n=19
g=[[0]*n for _ in range(n)]
# centers zero-indexed from observed input
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
# mark 3 cross arms at each plus
for r,c,v in centers:
    for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
        if 0<=rr<n and 0<=cc<n:g[rr][cc]=3
# extend row/column color, retaining markers
for r,c,v in centers:
    for j in range(n):
        if g[r][j]==0:g[r][j]=v
    for i in range(n):
        if g[i][c]==0:g[i][c]=v
print(g)
